<?php require 'db.php'; header('Content-Type: application/json; charset=utf-8'); try{$a=$_POST['accion']??$_GET['accion']??'listar'; if($a==='listar'){$s=$pdo->query('SELECT p.*,b.nombre barco_nombre,s.nombre socio_nombre,s.apellidos socio_apellidos FROM patron p LEFT JOIN barcos b ON b.no_matricula=p.barcos_no_matricula LEFT JOIN Socios s ON s.documento=p.Socios_documento ORDER BY p.nombre,p.apellido');echo json_encode(['ok'=>true,'datos'=>$s->fetchAll()],JSON_UNESCAPED_UNICODE);exit;} if($a==='crear'){$s=$pdo->prepare('INSERT INTO patron(documento,nombre,apellido,telefono,barcos_no_matricula,Socios_documento) VALUES(?,?,?,?,?,?)');$s->execute([trim($_POST['documento']),trim($_POST['nombre']),trim($_POST['apellido']),trim($_POST['telefono']??''),$_POST['barcos_no_matricula'],trim($_POST['Socios_documento'])]);echo json_encode(['ok'=>true,'mensaje'=>'Patrón creado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='actualizar'){$s=$pdo->prepare('UPDATE patron SET nombre=?,apellido=?,telefono=?,barcos_no_matricula=?,Socios_documento=? WHERE documento=?');$s->execute([trim($_POST['nombre']),trim($_POST['apellido']),trim($_POST['telefono']??''),$_POST['barcos_no_matricula'],trim($_POST['Socios_documento']),trim($_POST['documento'])]);echo json_encode(['ok'=>true,'mensaje'=>'Patrón actualizado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='eliminar'){$s=$pdo->prepare('DELETE FROM patron WHERE documento=?');$s->execute([trim($_POST['documento'])]);echo json_encode(['ok'=>true,'mensaje'=>'Patrón eliminado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>'Acción no válida.'],JSON_UNESCAPED_UNICODE);}catch(PDOException $e){http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
?>
